import java.util.*; public class FractionalKnapsack { public static double value(int budget,int[]price,double[]score){Integer[]idx=new Integer[price.length];for(int i=0;i<idx.length;i++)idx[i]=i;Arrays.sort(idx,(i,j)->Double.compare(score[j]/price[j],score[i]/price[i]));double v=0;for(int i:idx){if(budget<=0)break;int take=Math.min(budget,price[i]);v+=take*(score[i]/5.0);budget-=take;}return v;} }